// Tests for history, change over time and the forecast, and for the example flight.
// Run: npm test (Node 18+). Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fitLine, direction, crossing, forecast } from '../src/trend.js';
import { exampleFlight, MISSION } from '../src/demo-crew.js';
import { createMachine, STATUS } from '../src/engine.js';
import { CELLS, CREW, SHIP } from '../src/config.js';

const DAY = 24 * 60 * 60 * 1000;
const T0 = new Date('2026-06-01T00:00:00Z').getTime();
const day = (d) => new Date(T0 + d * DAY);

test('straight line through readings that lie on a line: exact slope per day', () => {
  const line = fitLine([0, 10, 20].map((d) => ({ t: day(d).getTime(), v: 40 - 0.5 * d })));
  assert.ok(Math.abs(line.perDay + 0.5) < 1e-9);
  assert.ok(Math.abs(line.at(day(30)) - 25) < 1e-9);
});

test('fewer than three readings: no line, the direction is unknown', () => {
  const line = fitLine([{ t: day(0).getTime(), v: 1 }, { t: day(1).getTime(), v: 2 }]);
  assert.equal(line, null);
  assert.equal(direction(line, 0.1), 'unknown');
});

test('direction: a change smaller than the flat threshold counts as flat', () => {
  const pts = (k) => [0, 10, 20].map((d) => ({ t: day(d).getTime(), v: 60 + k * d }));
  assert.equal(direction(fitLine(pts(0.001)), 0.01), 'flat');
  assert.equal(direction(fitLine(pts(0.5)), 0.01), 'up');
  assert.equal(direction(fitLine(pts(-0.5)), 0.01), 'down');
});

test('crossing: the first day the line goes below the lower border', () => {
  const line = fitLine([0, 10, 20].map((d) => ({ t: day(d).getTime(), v: 40 - 0.5 * d })));
  const c = crossing(line, { min: 30, max: null }, day(10), day(60));
  assert.equal(c.side, 'below');
  assert.equal(c.already, false);
  assert.ok(Math.abs(c.date.getTime() - day(20).getTime()) < 60 * 1000);
  assert.equal(crossing(line, { min: 10, max: null }, day(20), day(30)), null);
});

test('readings minutes apart on one day give no forecast, however steep they look', () => {
  const t = day(5).getTime();
  const history = [70, 80, 90].map((v, i) => ({ time: new Date(t + i * 60 * 1000), value: v }));
  const fc = forecast(history, { norm: { min: 60, max: 100 }, flatPerDay: 0.03, now: day(5), landing: day(60) });
  assert.equal(fc.line, null);
  assert.equal(fc.crossing, null);
  assert.equal(fc.days, 1);
});

test('a border passed between the last reading and today is still found', () => {
  const history = [0, 10, 20].map((d) => ({ time: day(d), value: 40 - 0.5 * d }));
  const fc = forecast(history, { norm: { min: 29, max: null }, flatPerDay: 0.01, now: day(40), landing: day(60) });
  assert.equal(fc.crossing.side, 'below');
  assert.equal(fc.crossing.already, false);
  assert.equal(fc.crossedBeforeNow, true);
});

test('empty and unreadable values are left out of the forecast', () => {
  const history = [{ time: day(0), value: '' }, { time: day(1), value: null }, { time: day(2), value: 'abc' }, { time: day(3), value: 5 }];
  assert.equal(forecast(history, { norm: null, flatPerDay: 0, now: day(3), landing: day(9) }).points, 1);
});

test('example flight: the same on every run, marked as an example, never past today', () => {
  const a = exampleFlight(CREW);
  const b = exampleFlight(CREW);
  assert.deepEqual(a, b);
  assert.ok(a.length > 1000);
  assert.ok(a.every((e) => e.example === true));
  assert.ok(a.every((e) => new Date(e.time) <= new Date(MISSION.today)));
});

test('example flight: every reading belongs to a known person or the ship, and the machine reads all of it', () => {
  const ids = new Set([...CREW, SHIP].map((p) => p.id));
  const machine = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true } });
  for (const ev of exampleFlight(CREW)) {
    assert.ok(ids.has(ev.person), ev.person);
    if (ev.kind === 'review') { machine.review(ev.person, ev.time); continue; }
    const env = CELLS.filter((c) => c.section === 'env').map((c) => c.indicator);
    if (ev.person === SHIP.id) assert.ok(env.includes(ev.reading.indicator), ev.reading.indicator);
    else assert.ok(!env.includes(ev.reading.indicator), ev.reading.indicator);
    const e = machine.receive({ ...ev.reading, person: ev.person, time: ev.time });
    assert.notEqual(e.status, STATUS.UNKNOWN, `${ev.person} ${ev.reading.indicator} ${JSON.stringify(ev.reading.value)}`);
  }
});

test('example flight: no strength tests in flight, as in the published studies', () => {
  const launch = new Date(MISSION.launch);
  const strength = exampleFlight(CREW).filter((e) => e.reading && e.reading.indicator === 'strength');
  assert.ok(strength.length > 0);
  assert.ok(strength.every((e) => new Date(e.time) < launch));
});

test("example flight: Elly's last endurance test is in the norm, and the line passes NASA's 80% limit after today but before landing", () => {
  const elly = CREW.find((p) => p.id === 'crew-2');
  const machine = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: {} });
  for (const ev of exampleFlight([elly])) if (ev.kind === 'reading') machine.receive({ ...ev.reading, person: ev.person, time: ev.time });
  const h = machine.history('crew-2', 'vo2max');
  assert.equal(h[h.length - 1].status, STATUS.OK);
  const fc = forecast(h, { norm: { min: elly.baselines.vo2max * 0.8, max: null }, flatPerDay: 0.004, now: MISSION.today, landing: MISSION.landing, window: { from: MISSION.launch, to: MISSION.landing } });
  assert.equal(fc.direction, 'down');
  assert.equal(fc.crossing.already, false);
  assert.ok(fc.crossing.date > new Date(MISSION.today));
  assert.ok(fc.crossing.date < new Date(MISSION.landing));
});
